(function(){'use strict';if(typeof window==='undefined')return;if(window.MwApiToast)return;function severityFor(data){var code=(data&&data.code)||'';if(!code)return'error';if(code==='DB_ERROR'||code==='SERVER_ERROR'||code==='NETWORK')return'warning';return'error'}
function showPlainToast(message,kind){if(typeof window.mwToast==='function'){window.mwToast(message,kind);return}
try{window.alert(message)}catch(_){}}
function show(data,onRetry){data=data||{};var kind=severityFor(data);var msg=data.error||'Something went wrong. Please try again.';try{if(window.MwHaptics){if(kind==='warning')window.MwHaptics.warning();else window.MwHaptics.error()}}catch(_){}
if(typeof onRetry==='function'&&data.retryable&&typeof window.mwToast==='function'){var container=document.getElementById('mw-toast-container')||createContainer();var toast=document.createElement('div');toast.className='mw-toast mw-toast--'+kind+' mw-toast--has-action';toast.setAttribute('role','alert');toast.setAttribute('aria-live','assertive');toast.setAttribute('aria-atomic','true');var msgEl=document.createElement('span');msgEl.className='mw-toast-msg';msgEl.textContent=msg;var retryBtn=document.createElement('button');retryBtn.type='button';retryBtn.className='mw-toast-action';retryBtn.textContent='Try again';retryBtn.setAttribute('data-haptic','tap');retryBtn.addEventListener('click',function(){dismiss(toast);try{onRetry()}catch(e){}});var closeBtn=document.createElement('button');closeBtn.type='button';closeBtn.className='mw-toast-close';closeBtn.setAttribute('aria-label','Dismiss');closeBtn.innerHTML='&times;';closeBtn.addEventListener('click',function(){dismiss(toast)});toast.appendChild(msgEl);toast.appendChild(retryBtn);toast.appendChild(closeBtn);container.appendChild(toast);setTimeout(function(){dismiss(toast)},8000);return}
showPlainToast(msg,kind)}
function createContainer(){var c=document.createElement('div');c.id='mw-toast-container';c.className='mw-toast-container';c.setAttribute('role','region');c.setAttribute('aria-label','Notifications');document.body.appendChild(c);return c}
function dismiss(toast){if(!toast||!toast.parentNode)return;toast.classList.add('mw-toast--leaving');setTimeout(function(){if(toast.parentNode)toast.parentNode.removeChild(toast);},250)}
window.MwApiToast={show:show}}())